import json, re

true = True
false = False
null = None

def to_dict(obj):
    if isinstance(obj, str):
        try: return json.loads(obj)
        except: return {}
    elif isinstance(obj, dict):
        return obj
    return {}

try:
    # 1. Lấy dữ liệu từ node Gemini 1 và Issue Key từ node 1
    raw_response = to_dict($gemini_1)
    issue_key = "$shuffle_tools_1.message.issue_key"

    # 2. Bóc tách body từ HTTP response của Gemini
    resp_body = raw_response.get("body", raw_response)
    if isinstance(resp_body, str):
        try: resp_body = json.loads(resp_body)
        except: pass

    candidates = resp_body.get("candidates", [])
    if not candidates:
        raise Exception("Gemini khong tra ve candidates nao!")

    text_content = candidates[0]["content"]["parts"][0]["text"].strip()

    # Gọt sạch dấu markdown nếu có
    cleaned_text = re.sub(r"^```json\s*", "", text_content)
    cleaned_text = re.sub(r"^```\s*", "", cleaned_text)
    cleaned_text = re.sub(r"\s*```$", "", cleaned_text)

    analysis = json.loads(cleaned_text)

    verdict = analysis.get("verdict", "SUSPICIOUS")
    verdict_reasoning = analysis.get("verdict_reasoning", "N/A")
    risk_level = analysis.get("risk_level", "TRUNG BINH")
    mitre_tech = analysis.get("mitre_technique", "N/A")
    summary = analysis.get("summary", "N/A")
    attacker_intent = analysis.get("attacker_intent", "N/A")
    remediations = analysis.get("remediation_actions", [])

    # Đổi màu Callout Panel tùy theo mức độ
    if verdict == "TRUE_POSITIVE" or risk_level in ["KHAN CAP", "CAO"]:
        panel_type = "error"     # Màu Đỏ nổi bật
    elif verdict == "FALSE_POSITIVE":
        panel_type = "success"   # Màu Xanh lá an toàn
    else:
        panel_type = "warning"   # Màu Vàng cảnh báo

    # Tạo các đoạn văn bản trong Panel
    panel_content = [
        {
            "type": "paragraph",
            "content": [
                {"type": "text", "text": "🤖 GOOGLE GEMINI - AI SOC TRIAGE", "marks": [{"type": "strong"}]},
                {"type": "text", "text": f"  [{verdict} | Mức độ: {risk_level}]", "marks": [{"type": "code"}]}
            ]
        },
        {
            "type": "paragraph",
            "content": [
                {"type": "text", "text": "🔍 Lập luận thẩm định (Verdict Reasoning): ", "marks": [{"type": "strong"}]},
                {"type": "text", "text": str(verdict_reasoning)}
            ]
        },
        {
            "type": "paragraph",
            "content": [
                {"type": "text", "text": "🎯 MITRE ATT&CK: ", "marks": [{"type": "strong"}]},
                {"type": "text", "text": str(mitre_tech), "marks": [{"type": "code"}]}
            ]
        },
        {
            "type": "paragraph",
            "content": [
                {"type": "text", "text": "📝 Tóm tắt sự cố: ", "marks": [{"type": "strong"}]},
                {"type": "text", "text": str(summary)}
            ]
        },
        {
            "type": "paragraph",
            "content": [
                {"type": "text", "text": "🥷 Ý đồ của Kẻ tấn công: ", "marks": [{"type": "strong"}]},
                {"type": "text", "text": str(attacker_intent)}
            ]
        }
    ]

    # Thêm danh sách hành động khuyến nghị
    remed_items = []
    for item in remediations:
        remed_items.append({
            "type": "listItem",
            "content": [{"type": "paragraph", "content": [{"type": "text", "text": str(item)}]}]
        })

    if remed_items:
        panel_content.append({
            "type": "paragraph",
            "content": [{"type": "text", "text": "🛡️ Hành động ứng phó khuyến nghị (Remediation):", "marks": [{"type": "strong"}]}]
        })
        panel_content.append({
            "type": "bulletList",
            "content": remed_items
        })

    # Đóng gói cấu trúc Jira ADF chuẩn v3
    adf_body = {
        "body": {
            "version": 1,
            "type": "doc",
            "content": [
                {
                    "type": "panel",
                    "attrs": {"panelType": panel_type},
                    "content": panel_content
                }
            ]
        }
    }

    print(json.dumps({
        "success": True,
        "issue_key": issue_key,
        "comment_payload": adf_body
    }))
except Exception as e:
    print(json.dumps({
        "success": False,
        "error": str(e),
        "issue_key": "$shuffle_tools_1.message.issue_key"
    }))

